// phase runs.
func (q *Queries) ListUnplacedCommitUnits(ctx context.Context, sessionID int64) ([]ImportUnit, error) {
	rows, err := q.db.QueryContext(ctx, listUnplacedCommitUnits, sessionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ImportUnit{}
	for rows.Next() {
		var i ImportUnit
		if err := rows.Scan(
			&i.ID,
			&i.SessionID,
			&i.RelPath,
			&i.Shape,
			&i.FileCount,
			&i.Bytes,
			&i.Confidence,
			&i.Decision,
			&i.WorkID,
			&i.EditionID,
			&i.EvidenceJson,
			&i.CandidatesJson,
			&i.Reason,
			&i.WorkCreated,
			&i.EditionCreated,
			&i.PackID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const recomputeImportSessionCounts = `-- name: RecomputeImportSessionCounts :exec
UPDATE import_session SET
  units_total = (SELECT COUNT(*) FROM import_unit iu WHERE iu.session_id = ?1),
  units_committed = (SELECT COUNT(*) FROM import_unit iu
                      WHERE iu.session_id = ?1 AND iu.decision = 'COMMIT'),
  units_queued = (SELECT COUNT(*) FROM import_unit iu
                   WHERE iu.session_id = ?1 AND iu.decision = 'QUEUE'),
  units_skipped = (SELECT COUNT(*) FROM import_unit iu
                     WHERE iu.session_id = ?1 AND iu.decision = 'SKIP'),
  units_failed = (SELECT COUNT(*) FROM import_unit iu
                    WHERE iu.session_id = ?1 AND iu.decision = 'FAILED'),
  bytes_imported = (SELECT COALESCE(SUM(iu.bytes), 0) FROM import_unit iu
                      WHERE iu.session_id = ?1 AND iu.decision = 'COMMIT')
WHERE id = ?1
`

// Recomputed from import_unit rather than incremented as units are added or
// redecided -- the same drift-and-repair shape CategoryCounters already uses,
// cheaper to reason about than keeping a running total consistent through
// every future call site that can change a unit's decision.
func (q *Queries) RecomputeImportSessionCounts(ctx context.Context, sessionID int64) error {
	_, err := q.db.ExecContext(ctx, recomputeImportSessionCounts, sessionID)
	return err
}

const requestImportSessionCancel = `-- name: RequestImportSessionCancel :execrows
UPDATE import_session SET state = 'CANCELLING'
WHERE id = ?1 AND state = 'INSPECTING'
`

// Only from INSPECTING: refuses a no-op cancel of an already-terminal session
// and never overwrites CANCELLING with itself. :execrows lets the caller
// distinguish "already stopped/never running" (0 rows) from "now stopping".
func (q *Queries) RequestImportSessionCancel(ctx context.Context, id int64) (int64, error) {
	result, err := q.db.ExecContext(ctx, requestImportSessionCancel, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const setImportSessionCategory = `-- name: SetImportSessionCategory :execrows
UPDATE import_session SET category_id = ?1
WHERE id = ?2 AND (category_id IS NULL OR category_id = ?1)
`

type SetImportSessionCategoryParams struct {
	CategoryID sql.NullInt64
	ID         int64
}

// From no category, or a no-op onto the same one -- the second form is what
// makes re-running the placement catch-up idempotent (a caller retrying
// after a transient placement failure, e.g. capacity not probed yet, sends
// the same category_id again). Re-pointing at a *different* category is out
// of scope, still refused. :execrows lets the caller tell that apart from
// "no such session".
func (q *Queries) SetImportSessionCategory(ctx context.Context, arg SetImportSessionCategoryParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, setImportSessionCategory, arg.CategoryID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

