const setImportUnitDecision = `-- name: SetImportUnitDecision :exec
UPDATE import_unit SET decision = ?1, confidence = ?2,
                        work_id = ?3, edition_id = ?4,
                        candidates_json = ?5, reason = ?6
WHERE id = ?7
`

type SetImportUnitDecisionParams struct {
	Decision       string
	Confidence     float64
	WorkID         sql.NullInt64
	EditionID      sql.NullInt64
	CandidatesJson sql.NullString
	Reason         sql.NullString
	ID             int64
}

// The only mutation IDENTIFY needs once it exists: a unit starts QUEUE with no
// identity (F29's own default) and this is what fills in a real result later,
// without this package needing to know how that result was produced.
func (q *Queries) SetImportUnitDecision(ctx context.Context, arg SetImportUnitDecisionParams) error {
	_, err := q.db.ExecContext(ctx, setImportUnitDecision,
		arg.Decision,
		arg.Confidence,
		arg.WorkID,
		arg.EditionID,
		arg.CandidatesJson,
		arg.Reason,
		arg.ID,
	)
	return err
}

const setImportUnitPlacement = `-- name: SetImportUnitPlacement :exec
UPDATE import_unit SET work_id = ?1, edition_id = ?2,
                        work_created = ?3,
                        edition_created = ?4
WHERE id = ?5
`

type SetImportUnitPlacementParams struct {
	WorkID         sql.NullInt64
	EditionID      sql.NullInt64
	WorkCreated    int64
	EditionCreated int64
	ID             int64
}

// The IMPORTING phase's own write, once placement.Resolve, the move and
// ResolveWorksDetailed have all succeeded for one unit -- work_id becoming
// non-null is what "actually placed" means from here on.
func (q *Queries) SetImportUnitPlacement(ctx context.Context, arg SetImportUnitPlacementParams) error {
	_, err := q.db.ExecContext(ctx, setImportUnitPlacement,
		arg.WorkID,
		arg.EditionID,
		arg.WorkCreated,
		arg.EditionCreated,
		arg.ID,
	)
	return err
}
